  li.dataset.type = item.type;
  li.tabIndex = 0;
  li.setAttribute("aria-label", item.text + ". Перетащите или используйте Alt и стрелки вверх-вниз, чтобы изменить порядок.");
  li.innerHTML = `<span class="drag-handle">${HANDLE_SVG}</span><span class="item-text"></span>`;
  li.querySelector(".item-text").textContent = item.text;
  return li;
}

function buildTest() {
  tabsEl.innerHTML = "";
  STEP_NAMES.forEach((name, step) => {
    const tab = document.createElement("button");
    tab.type = "button";
    tab.className = "step-tab";
    tab.id = "step-tab-" + step;
    tab.setAttribute("role", "tab");
    tab.setAttribute("aria-controls", "step-pane-" + step);
    tab.setAttribute("aria-selected", "false");
    tab.textContent = name;
    tab.addEventListener("click", () => setStep(step));
    tabsEl.appendChild(tab);
  });

  panesEl.innerHTML = "";
  for (let step = 0; step < 8; step++) {
    const pane = document.createElement("div");
    pane.className = "pane";
    pane.id = "step-pane-" + step;
    pane.setAttribute("role", "tabpanel");
    pane.setAttribute("aria-labelledby", "step-tab-" + step);
    if (step !== 0) pane.hidden = true;

    const cards = document.createElement("div");
    cards.className = "cards";

    for (let cardIndex = 0; cardIndex < 3; cardIndex++) {
      const listIndex = step * 3 + cardIndex;
      const card = document.createElement("div");
      card.className = "card";

      const top = document.createElement("div");
      top.className = "card-label";
      top.textContent = "Я наиболее";

      const list = document.createElement("ul");
      list.className = "disc-list";
      list.dataset.list = String(listIndex);
      list.setAttribute("aria-label", "Я наиболее — Я наименее, шаг " + (step + 1) + ", блок " + (cardIndex + 1));

      QUESTIONS[listIndex].forEach((item) => list.appendChild(makeItem(item)));

      const bottom = document.createElement("div");
      bottom.className = "card-label card-label--bottom";
      bottom.textContent = "Я наименее";

      card.append(top, list, bottom);
      cards.appendChild(card);
    }

    pane.appendChild(cards);
    panesEl.appendChild(pane);
  }
}

